-- glossary
insert into public.knowledge_glossary (term, definition, related_article_id) values ('BMI', $md$Body Mass Index — angka yang dihitung dari berat dan tinggi badan untuk menggambarkan kategori berat secara umum (kurus, normal, overweight, obesitas). Praktis tapi terbatas: BMI tidak bisa membedakan otot dan lemak, jadi bukan diagnosis kesehatan.$md$, (select id from public.knowledge_articles where slug = 'bmi-itu-apa')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('BMR', $md$Basal Metabolic Rate — jumlah kalori yang dibakar tubuhmu saat istirahat total, hanya untuk menjaga fungsi dasar seperti bernapas dan detak jantung. Biasanya dihitung dengan rumus Mifflin-St Jeor dari umur, jenis kelamin, tinggi, dan berat.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('TDEE', $md$Total Daily Energy Expenditure — total kalori yang kamu bakar dalam sehari, yaitu BMR ditambah aktivitas fisik dan pencernaan makanan. Angka inilah yang jadi patokan kebutuhan kalori harianmu.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Kalori', $md$Satuan energi dari makanan dan minuman. Tubuh memakainya untuk semua aktivitas, dari bernapas sampai olahraga. Kalori itu netral — bukan musuh, tapi juga perlu dikelola.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Defisit kalori', $md$Kondisi saat kalori yang masuk lebih sedikit dari yang dibakar tubuh (TDEE). Ini prinsip dasar penurunan berat yang sehat — idealnya defisit ringan sekitar 300–500 kkal per hari, bukan ekstrem.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Surplus kalori', $md$Kondisi saat kalori yang masuk lebih banyak dari yang dibakar tubuh. Dibutuhkan kalau targetmu menaikkan berat badan atau membangun massa otot — tetap sebaiknya bertahap dan dari makanan bergizi.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Protein', $md$Zat gizi pembangun otot dan jaringan tubuh, juga bikin kenyang lebih lama dibanding karbohidrat atau lemak. Sumbernya: telur, ayam, ikan, tahu, tempe, dan kacang-kacangan.$md$, (select id from public.knowledge_articles where slug = 'protein-fondasi')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Karbohidrat', $md$Sumber energi utama tubuh, dipecah menjadi glukosa sebagai bahan bakar otak dan otot. Tidak perlu dihindari total — pilih yang berserat seperti nasi merah, oat, dan umbi-umbian.$md$, (select id from public.knowledge_articles where slug = 'kalori-itu-energi')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Lemak', $md$Zat gizi sumber energi cadangan yang juga penting untuk hormon dan penyerapan vitamin. Yang perlu dibatasi adalah lemak trans dan lemak jenuh berlebih, bukan semua lemak.$md$, null) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Serat', $md$Bagian tumbuhan yang tidak dicerna tubuh, tapi bikin kenyang lebih lama dan membantu pencernaan. Ada di sayur, buah, dan biji-bijian utuh.$md$, (select id from public.knowledge_articles where slug = 'serat-kenyang-lebih-lama')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Metabolisme', $md$Semua proses kimia di tubuh yang mengubah makanan menjadi energi. Kecepatannya dipengaruhi massa otot, umur, dan aktivitas — bukan sesuatu yang 'rusak' permanen karena sekali diet.$md$, (select id from public.knowledge_articles where slug = 'bmr-tdee-bahasa-manusia')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Massa otot', $md$Total otot di tubuhmu. Otot membakar lebih banyak kalori dibanding lemak bahkan saat istirahat, jadi menjaga massa otot penting saat menurunkan berat badan.$md$, (select id from public.knowledge_articles where slug = 'otot-vs-lemak')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Lemak visceral', $md$Lemak yang menumpuk di sekitar organ dalam perut. Jenis ini lebih berkaitan dengan risiko kesehatan dibanding lemak di bawah kulit, dan lingkar pinggang adalah cara sederhana memantaunya.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Lingkar pinggang', $md$Ukuran keliling perut setinggi pusar. Pelengkap BMI yang murah dan gampang: umumnya dianjurkan di bawah 90 cm untuk pria dan 80 cm untuk wanita Asia.$md$, (select id from public.knowledge_articles where slug = 'lingkar-pinggang')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Plateau', $md$Fase saat berat badan berhenti turun padahal pola makan dan aktivitas tidak berubah. Ini normal — tubuh beradaptasi — dan biasanya terlewati dengan evaluasi porsi, aktivitas, atau sekadar bersabar.$md$, null) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Yo-yo dieting', $md$Pola turun-naik berat badan berulang akibat diet ekstrem yang tidak bertahan lama. Selain melelahkan mental, pola ini bikin makin sulit menjaga berat stabil jangka panjang.$md$, (select id from public.knowledge_articles where slug = 'diet-ekstrem-vs-pola-makan')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Indeks glikemik', $md$Skala seberapa cepat suatu makanan menaikkan gula darah. Makanan indeks glikemik rendah (mis. oat, kacang) menaikkan gula darah lebih perlahan dan bikin kenyang lebih lama.$md$, null) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Gula darah', $md$Kadar glukosa di dalam darah, sumber energi utama sel tubuh. Naik-turunnya dipengaruhi makanan, aktivitas, tidur, dan stres — bukan cuma soal makan manis.$md$, null) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Porsi', $md$Jumlah makanan yang kamu ambil dalam sekali makan. Mengatur porsi — misalnya dengan piring lebih kecil atau berhenti sebelum terlalu kenyang — adalah cara paling sederhana mengendalikan asupan tanpa diet ketat.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('NEAT', $md$Non-Exercise Activity Thermogenesis — kalori yang terbakar dari aktivitas sehari-hari di luar olahraga: jalan kaki, naik tangga, beres-beres rumah. Sering diremehkan, padahal kontribusinya besar.$md$, (select id from public.knowledge_articles where slug = 'jalan-kaki-underrated')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Latihan kekuatan', $md$Olahraga melawan beban — angkat beban, push-up, squat — yang membangun dan menjaga massa otot. Penting terutama saat defisit kalori agar yang susut lemak, bukan otot.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Kardio', $md$Olahraga yang memacu jantung dan napas: lari, bersepeda, berenang, jalan cepat. Bagus untuk stamina dan membakar kalori, paling efektif kalau dilakukan rutin, bukan sesekali tapi brutal.$md$, (select id from public.knowledge_articles where slug = 'konsistensi-vs-intensitas')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Hidrasi', $md$Kecukupan cairan tubuh. Kadang rasa haus disalahartikan sebagai lapar, jadi minum cukup sebelum makan bisa membantu mengendalikan porsi secara alami.$md$, null) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Mindful eating', $md$Makan dengan penuh perhatian: mengunyah pelan, merasakan rasa, dan berhenti saat cukup kenyang. Lawan dari makan sambil scroll HP sampai piring kosong tanpa sadar.$md$, (select id from public.knowledge_articles where slug = 'mindful-eating')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();
insert into public.knowledge_glossary (term, definition, related_article_id) values ('Sleep hygiene', $md$Kebiasaan tidur yang sehat: jadwal tidur teratur, kurangi layar sebelum tidur, dan kamar yang gelap dan sejuk. Kurang tidur mengacaukan hormon lapar-kenyang dan bikin gampang ngemil.$md$, (select id from public.knowledge_articles where slug = 'tidur-dan-berat-badan')) on conflict (term) do update set definition = excluded.definition, related_article_id = excluded.related_article_id, updated_at = now();

-- quizzes
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at) values ('kuis-bmi-dasar', 'Seberapa paham kamu soal BMI?', '5 soal cepat tentang arti dan batas BMI.', (select id from public.knowledge_articles where slug = 'bmi-itu-apa'), 'published', now()) on conflict (slug) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar'), 0, 'BMI dihitung berdasarkan apa?', '["Berat badan dan tinggi badan", "Berat badan dan umur", "Lingkar pinggang dan tinggi badan", "Berat badan dan kadar lemak darah"]'::jsonb, 0, 'Rumus BMI sederhana: berat (kg) dibagi tinggi (m) kuadrat. Makanya praktis, tapi juga makanya ia tidak tahu komposisi tubuhmu.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar'), 1, 'BMI 22,5 masuk kategori apa untuk orang dewasa?', '["Underweight", "Normal", "Overweight", "Obesitas"]'::jsonb, 1, 'Rentang normal BMI dewasa adalah 18,5–24,9. Angka 22,5 duduk manis di tengahnya.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar'), 2, 'Apa keterbatasan utama BMI?', '["Rumusnya terlalu rumit untuk dipakai sehari-hari", "Tidak bisa membedakan massa otot dan lemak", "Hanya berlaku untuk orang yang sudah diet", "Berubah-ubah tergantung jam makan"]'::jsonb, 1, 'Atlet berotot bisa tercatat ''overweight'' padahal kadar lemaknya rendah. BMI itu skrining awal, bukan vonis.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar'), 3, 'Untuk anak dan remaja, penilaian BMI sebaiknya bagaimana?', '["Pakai kategori dewasa yang sama persis", "Tidak perlu diukur sampai umur 20 tahun", "Memakai kurva pertumbuhan/persentil sesuai umur dan jenis kelamin", "Cukup ditebak dari penampilan fisik"]'::jsonb, 2, 'Anak masih bertumbuh, jadi BMI-nya dibaca lewat persentil di kurva pertumbuhan — kategori dewasa tidak berlaku mentah-mentah.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-bmi-dasar'), 4, 'Seseorang dengan BMI 27 sebaiknya menyimpulkan apa?', '["Pasti tidak sehat dan harus diet ketat segera", "Masuk kategori overweight — jadikan pemicu untuk cek pola hidup secara menyeluruh", "BMI di atas 25 selalu berarti obesitas", "Tidak perlu peduli karena BMI tidak akurat sama sekali"]'::jsonb, 1, 'BMI 27 = overweight, tapi itu titik awal evaluasi (pola makan, aktivitas, lingkar pinggang), bukan diagnosis penyakit.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at) values ('kuis-kalori-energi', 'Kalori & Energi', 'Tebak-tebakan soal kalori, BMR, dan TDEE.', (select id from public.knowledge_articles where slug = 'kalori-itu-energi'), 'published', now()) on conflict (slug) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi'), 0, 'Sebenarnya kalori itu apa?', '["Zat berbahaya dalam makanan cepat saji", "Satuan energi yang dipakai tubuh untuk beraktivitas", "Jenis lemak yang menumpuk di perut", "Hormon yang bikin cepat lapar"]'::jsonb, 1, 'Kalori hanyalah satuan energi — tubuhmu butuh itu untuk bernapas, berpikir, sampai olahraga. Masalahnya cuma soal jumlah.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi'), 1, 'BMR menggambarkan apa?', '["Kalori yang terbakar saat olahraga intens", "Kalori maksimal yang boleh dimakan sehari", "Kalori yang dibakar tubuh saat istirahat total", "Kecepatan metabolisme setelah makan besar"]'::jsonb, 2, 'BMR adalah energi untuk fungsi dasar tubuh saat kamu rebahan seharian tanpa ngapa-ngapain — biasanya dihitung dengan rumus Mifflin-St Jeor.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi'), 2, 'Hubungan TDEE dan BMR yang benar adalah…', '["TDEE selalu lebih kecil dari BMR", "TDEE = BMR + energi aktivitas harian", "TDEE dan BMR adalah dua nama untuk hal yang sama", "TDEE hanya berlaku untuk atlet"]'::jsonb, 1, 'TDEE adalah total harian: BMR ditambah semua aktivitasmu. Inilah angka yang jadi patokan kebutuhan kalorimu.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi'), 3, 'Defisit kalori artinya…', '["Tidak makan sama sekali seharian", "Kalori masuk lebih sedikit dari yang dibakar tubuh", "Menghindari semua makanan berkalori tinggi selamanya", "Olahraga sampai kalori terbakar habis"]'::jsonb, 1, 'Defisit ringan sekitar 300–500 kkal per hari sudah cukup untuk turun berat secara sehat — tidak perlu sampai menyiksa diri.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-kalori-energi'), 4, 'Perkiraan energi yang tersimpan dalam 1 kg lemak tubuh adalah sekitar…', '["3.500 kkal", "5.000 kkal", "7.700 kkal", "10.000 kkal"]'::jsonb, 2, 'Sekitar 7.700 kkal per kg lemak — makanya target realistis adalah turun bertahap sekitar 0,5 kg per minggu, bukan instan.');
insert into public.knowledge_quizzes (slug, title, description, article_id, status, published_at) values ('kuis-mitos-fakta', 'Mitos vs Fakta Kebiasaan Sehat', 'Bedakan mitos populer dari faktanya.', null, 'published', now()) on conflict (slug) do update set title = excluded.title, description = excluded.description, status = 'published', updated_at = now();
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta') and sort_order = 0; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta'), 0, 'Mitos atau fakta: ''Makan malam pasti bikin gemuk.''', '["Fakta — makan di atas jam 7 malam otomatis jadi lemak", "Mitos — yang menentukan adalah total kalori seharian, bukan jam makan", "Fakta — metabolisme berhenti total saat tidur", "Mitos — makan malam justru membakar kalori"]'::jsonb, 1, 'Tubuh tidak punya jam ajaib yang mengubah makanan jadi lemak tepat jam 7. Total asupan seharianlah yang menentukan.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta') and sort_order = 1; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta'), 1, 'Mitos atau fakta: ''Makin banyak keringat saat olahraga, makin banyak lemak terbakar.''', '["Fakta — keringat adalah lemak yang mencair", "Mitos — keringat terutama air; lemak keluar lewat napas dan metabolisme", "Fakta — berlaku untuk semua jenis olahraga", "Mitos — keringat tidak ada hubungannya sama sekali dengan olahraga"]'::jsonb, 1, 'Keringat adalah cara tubuh mendinginkan diri, isinya mostly air. Lemak yang terbakar justru sebagian besar keluar sebagai karbon dioksida lewat napas.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta') and sort_order = 2; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta'), 2, 'Mitos atau fakta: ''Karbohidrat harus dihindari total biar berat turun.''', '["Fakta — karbohidrat adalah satu-satunya penyebab kegemukan", "Mitos — karbohidrat adalah sumber energi utama; yang penting jenis dan porsinya", "Fakta — tubuh tidak membutuhkan karbohidrat sama sekali", "Mitos — karbohidrat tidak mengandung kalori"]'::jsonb, 1, 'Otak dan otot butuh glukosa dari karbohidrat. Pilih yang berserat dan atur porsinya — tidak perlu memusuhi satu zat gizi.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta') and sort_order = 3; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta'), 3, 'Mitos atau fakta: ''Menimbang badan tiap hari itu wajib biar berhasil.''', '["Fakta — tanpa timbangan harian diet pasti gagal", "Mitos — yang penting jadwal konsisten dan membaca tren, bukan angka harian", "Fakta — berat harian tidak pernah fluktuatif", "Mitos — menimbang justru dilarang total"]'::jsonb, 1, 'Berat harian naik-turun karena air dan makanan. Timbang dengan jadwal yang sama tiap minggu dan lihat trennya — itu data yang jujur.');
delete from public.knowledge_quiz_questions where quiz_id = (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta') and sort_order = 4; insert into public.knowledge_quiz_questions (quiz_id, sort_order, prompt, options, correct_index, explanation) values ( (select id from public.knowledge_quizzes where slug = 'kuis-mitos-fakta'), 4, 'Mitos atau fakta: ''Kurang tidur bisa mengganggu pengelolaan berat badan.''', '["Mitos — tidur tidak ada hubungannya dengan berat badan", "Fakta — kurang tidur mengacaukan hormon lapar-kenyang dan bikin gampang ngemil", "Mitos — begadang justru membakar lebih banyak kalori", "Fakta — kurang tidur langsung menambah 5 kg"]'::jsonb, 1, 'Kurang tidur menaikkan hormon lapar (ghrelin) dan menurunkan hormon kenyang (leptin). Tidur cukup adalah bagian strategi yang sah.');
